-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.card_rows_from_a_page_behind()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  seen text := nullif(current_setting('request.headers', true), '')::json ->> 'x-card-sync';
begin
  if seen ~ '^[0-9]{1,15}$' then
    update public.card_sync k set repair_from = least(coalesce(k.repair_from, seen::bigint), seen::bigint)
     where k.user_id = new.user_id and k.synced_to > seen::bigint;
  end if;
  return null;
end;
$function$;

grant execute on function public.card_rows_from_a_page_behind() to anon;
grant execute on function public.card_rows_from_a_page_behind() to authenticated;
grant execute on function public.card_rows_from_a_page_behind() to service_role;
